class Solution:
    def minCuttingCost(self, n: int, m: int, k: int) -> int:
        x = max(n, m)
        return 0 if x <= k else k * (x - k)

#include <algorithm>

class Solution {
public:
    long long minCuttingCost(int n, int m, int k) {
        int x = std::max(n, m);
        return x <= k ? 0 : 1LL * k * (x - k);
    }
};

class Solution {
    public long minCuttingCost(int n, int m, int k) {
        int x = Math.max(n, m);
        return x <= k ? 0 : (long) k * (x - k);
    }
}

/**
 * @param {number} n
 * @param {number} m
 * @param {number} k
 * @return {number}
 */
var minCuttingCost = function(n, m, k) {
    const x = Math.max(n, m);
    return x <= k ? 0 : k * (x - k);
};
